<script setup lang="ts">
import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {http} from '../api/http';import {useAuthStore} from '../stores/auth';const router=useRouter(),auth=useAuthStore(),loading=ref(false),form=reactive({currentPassword:'',newPassword:'',confirmPassword:''})
async function submit(){if(form.newPassword!==form.confirmPassword){ElMessage.error('两次输入的新密码不一致');return}loading.value=true;try{await http.put('/user/password',form);auth.clearSession();ElMessage.success('密码已修改，请使用新密码重新登录');router.replace('/login')}finally{loading.value=false}}
async function logout(){await auth.logout();router.replace('/login')}
</script>
<template><div class="change-page"><div class="change-card surface"><div class="lock">↻</div><p class="eyebrow">SECURITY INITIALIZATION</p><h1>首次登录，请设置新密码</h1><p class="hint">引导密码仅用于一次性初始化。完成修改后，当前会话会被撤销。</p><el-alert title="新密码至少 8 位，需包含大小写字母和数字，且不得继续使用引导密码。" type="warning" :closable="false"/><el-form label-position="top"><el-form-item label="当前引导密码"><el-input v-model="form.currentPassword" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新密码"><el-input v-model="form.newPassword" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认新密码"><el-input v-model="form.confirmPassword" type="password" show-password autocomplete="new-password"/></el-form-item><el-button type="primary" size="large" :loading="loading" class="full" @click="submit">设置密码并重新登录</el-button><el-button class="full exit" @click="logout">退出登录</el-button></el-form></div></div></template>
<style scoped>.change-page{min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at top,#e6f3f8,#f4f7fa 50%)}.change-card{width:480px;padding:38px}.lock{width:48px;height:48px;border-radius:13px;background:#e6f2f7;color:#22708f;display:grid;place-items:center;font-size:24px}.eyebrow{font-size:9px;letter-spacing:.2em;color:#3280a0;margin-top:20px}.change-card h1{font-size:25px;margin:8px 0}.hint{font-size:12px;line-height:1.7;color:#7d8b9d;margin-bottom:20px}.el-form{margin-top:22px}.full{width:100%}.exit{margin:10px 0 0}</style>
